const envelope = $json.body ?? $json;
const fail = (message) => { throw new Error('A001 contract validation failed: ' + message); };
const requiredString = (value, field) => {
  if (typeof value !== 'string' || value.trim().length === 0) fail(field + ' must be a non-empty string');
  return value.trim();
};
if (envelope.event_type !== 'market.research.requested') fail('event_type must be market.research.requested');
if (envelope.event_version !== '1.0') fail('event_version must be 1.0');
requiredString(envelope.event_id, 'event_id');
requiredString(envelope.source, 'source');
requiredString(envelope.company_id, 'company_id');
requiredString(envelope.entity_type, 'entity_type');
requiredString(envelope.entity_id, 'entity_id');
requiredString(envelope.correlation_id, 'correlation_id');
if (!envelope.occurred_at || Number.isNaN(Date.parse(envelope.occurred_at))) fail('occurred_at must be a valid ISO-8601 timestamp');
if (envelope.causation_id !== null && envelope.causation_id !== undefined && typeof envelope.causation_id !== 'string') fail('causation_id must be a string or null');
if (!envelope.metadata || typeof envelope.metadata !== 'object' || Array.isArray(envelope.metadata)) fail('metadata must be an object');
if (!envelope.payload || typeof envelope.payload !== 'object' || Array.isArray(envelope.payload)) fail('payload must be an object');
const body = envelope.payload;
const research_question = requiredString(body.research_question, 'payload.research_question');
const target_market = requiredString(body.target_market, 'payload.target_market');
if (body.source_policy !== undefined && (body.source_policy === null || typeof body.source_policy !== 'object' || Array.isArray(body.source_policy))) fail('payload.source_policy must be an object');
if (body.competitor_set !== undefined && (!Array.isArray(body.competitor_set) || body.competitor_set.some(x => typeof x !== 'string'))) fail('payload.competitor_set must be an array of strings');
const input = {
  research_question,
  target_market,
  geography: body.geography,
  industry: body.industry,
  customer_segment: body.customer_segment,
  time_horizon: body.time_horizon,
  competitor_set: body.competitor_set,
  source_policy: body.source_policy,
  output_format: body.output_format
};
return [{ json: {
  event_id: envelope.event_id,
  event_type: envelope.event_type,
  event_version: envelope.event_version,
  company_id: envelope.company_id,
  correlation_id: envelope.correlation_id,
  causation_id: envelope.causation_id ?? null,
  source: envelope.source,
  received_at: new Date().toISOString(),
  agent_id: 'A001',
  agent_name: 'Market Research Agent',
  input,
  runtime_invoked: false,
  status: 'validated_pending_runtime'
} }];
